CREATE TABLE registri_contabili (
    id SERIAL PRIMARY KEY,
    data DATE NOT NULL,
    descrizione TEXT,
    ammontare_lordo NUMERIC(12,2) NOT NULL CHECK (ammontare_lordo >= 0),
    tipo_transazione TEXT CHECK (tipo_transazione IN ('DEBITO', 'CREDITO')),
    riferimento_esterno TEXT
);

CREATE INDEX idx_registri_data ON registri_contabili(data);
CREATE INDEX idx_registri_tipo ON registri_contabili(tipo_transazione);
